<?php
require_once __DIR__ . '/../includes/functions.php'; require_admin(); $pdo=db();
$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');
if(!date_is_valid($from))$from=date('Y-m-01');if(!date_is_valid($to))$to=date('Y-m-d');if($from>$to){$tmp=$from;$from=$to;$to=$tmp;}
$st=$pdo->prepare("SELECT COUNT(*) bookings,COALESCE(SUM(total_amount),0) booking_value,COALESCE(SUM(status='confirmed'),0) confirmed,COALESCE(SUM(status='checked_in'),0) checked_in,COALESCE(SUM(status='completed'),0) completed,COALESCE(SUM(status='cancelled'),0) cancelled FROM bookings WHERE DATE(created_at) BETWEEN ? AND ?");$st->execute([$from,$to]);$b=$st->fetch();
$st=$pdo->prepare("SELECT COALESCE(SUM(amount),0) total,COALESCE(SUM(status='verified'),0) verified_count,COALESCE(SUM(CASE WHEN status='verified' THEN amount ELSE 0 END),0) verified_amount,COALESCE(SUM(status='pending'),0) pending_count FROM payment_records WHERE DATE(created_at) BETWEEN ? AND ?");$st->execute([$from,$to]);$pay=$st->fetch();
$st=$pdo->prepare("SELECT r.name,COUNT(b.id) booking_count,COALESCE(SUM(b.total_amount),0) revenue FROM rooms r LEFT JOIN bookings b ON b.room_id=r.id AND DATE(b.created_at) BETWEEN ? AND ? GROUP BY r.id ORDER BY booking_count DESC,r.name");$st->execute([$from,$to]);$roomStats=$st->fetchAll();
$pageTitle='Reports';include __DIR__.'/../includes/header.php';?>
<section class="admin-page container"><div class="admin-heading"><div><p class="eyebrow">MODULE 5 · ADMIN & REPORTS</p><h1>Business <em>overview.</em></h1><p class="muted">Review booking activity and recorded payments for a selected period.</p></div><div class="admin-actions"><a class="button button-outline" href="<?= BASE_URL ?>/admin/index.php">← Dashboard</a><a class="text-link" href="<?= BASE_URL ?>/admin/logout.php">Sign out ↗</a></div></div>
<form method="get" class="add-room-card" style="display:flex;gap:16px;align-items:end;flex-wrap:wrap;margin-bottom:28px"><div><label for="from">From date</label><input id="from" name="from" type="date" value="<?= e($from) ?>" required></div><div><label for="to">To date</label><input id="to" name="to" type="date" value="<?= e($to) ?>" required></div><button class="button button-dark">Run report</button><button class="button button-outline" type="button" onclick="window.print()">Print report</button></form>
<p class="muted">Period: <?= e($from) ?> through <?= e($to) ?> · Booking totals are based on booking creation date, not stay date.</p>
<div class="stats-grid"><div class="stat-card"><span>Bookings created</span><strong><?= (int)$b['bookings'] ?></strong></div><div class="stat-card"><span>Booking value</span><strong><?= money($b['booking_value']) ?></strong></div><div class="stat-card"><span>Verified payments</span><strong><?= money($pay['verified_amount']) ?></strong></div><div class="stat-card"><span>Pending payment records</span><strong><?= (int)$pay['pending_count'] ?></strong></div></div>
<div class="stats-grid"><div class="stat-card"><span>Confirmed</span><strong><?= (int)$b['confirmed'] ?></strong></div><div class="stat-card"><span>Checked in</span><strong><?= (int)$b['checked_in'] ?></strong></div><div class="stat-card"><span>Completed stays</span><strong><?= (int)$b['completed'] ?></strong></div><div class="stat-card"><span>Cancelled</span><strong><?= (int)$b['cancelled'] ?></strong></div></div>
<div class="admin-table-wrap"><div class="table-heading"><div><p class="eyebrow">ROOM PERFORMANCE</p><h2>Bookings by room</h2></div></div><div class="table-scroll"><table><thead><tr><th>Room</th><th>Bookings created</th><th>Booking value</th></tr></thead><tbody><?php foreach($roomStats as $r):?><tr><td><?= e($r['name']) ?></td><td><?= (int)$r['booking_count'] ?></td><td><?= money($r['revenue']) ?></td></tr><?php endforeach;?></tbody></table></div></div>
<p class="fine-print">Reports are operational summaries, not audited financial statements. Only manually verified payment records are included in verified collections. Online demo checkouts are not real transactions.</p></section><?php include __DIR__.'/../includes/footer.php'; ?>